+/// <summary>Tools available to the research agent.</summary>
+class ResearchTools
+{
+    private readonly List<string> _notes = [];
+    private readonly HttpClient _httpClient = new();
+
+    [Description("Search the web for information on a query. Returns search result snippets.")]
+    public async Task<string> SearchWeb([Description("The search query")] string query)
+    {
+        Console.WriteLine($"  [Tool] Searching: \"{query}\"");
+
+        try
+        {
+            // Use DuckDuckGo instant answer API as a free search source
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+            var result = await _httpClient.GetFromJsonAsync<JsonElement>(url);
+
+            var snippets = new List<string>();
+
+            // Extract abstract
+            var abstractText = result.GetProperty("AbstractText").GetString();
+            if (!string.IsNullOrEmpty(abstractText))
+                snippets.Add($"Summary: {abstractText}");
+
+            // Extract related topics
+            if (result.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
+            {
+                foreach (var topic in topics.EnumerateArray().Take(5))
+                {
+                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
+                    if (!string.IsNullOrEmpty(text))
+                        snippets.Add(text);
+                }
+            }
+
+            if (snippets.Count == 0)
+                return $"No detailed results found for '{query}'. Try a different search query.";
+
+            return string.Join("\n\n", snippets);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}. Try a different query.";
+        }
+    }
+
+    [Description("Take a note to remember a key finding during research.")]
+    public string TakeNote([Description("The note content to save")] string note)
+    {
+        _notes.Add(note);
+        Console.WriteLine($"  [Tool] Note taken ({_notes.Count} total)");
+        return $"Note saved. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieve all notes taken during the research session.")]
+    public string GetNotes()
+    {
+        Console.WriteLine("  [Tool] Retrieving all notes");
+        if (_notes.Count == 0)
+            return "No notes taken yet.";
+
+        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
+    }
+
+    public List<string> GetAllNotes() => [.. _notes];
+}
